
use anyhow::{Result, bail}; use image::GrayImage; pub fn decode_image(img_path: &str) -> Result<Vec<u8>> { let img = image::open(img_path)?.to_luma8(); let binary = binarize_otsu(&img); let (tl, tr, bl, br) = find_markers(&binary, img.width(), img.height())?; let start_x = tl.0 + 25; let start_y = tl.1 + 25; let end_x = tr.0 - 5; let end_y = bl.1 - 5; let mut bits = Vec::new(); for y in start_y..end_y { for x in start_x..end_x { let mut sum = 0; let mut count = 0; for dy in -1..=1 { for dx in -1..=1 { let nx = x as i32 + dx; let ny = y as i32 + dy; if nx >= 0 && ny >= 0 && (nx as u32) < img.width() && (ny as u32) < img.height() { sum += binary[(ny as u32, nx as u32)]; count += 1; } } } let avg = sum / count; bits.push(if avg < 128 { 0 } else { 1 }); } } let mut payload = Vec::new(); for chunk in bits.chunks(8) { if chunk.len() == 8 { let mut byte = 0u8; for (i, &bit) in chunk.iter().enumerate() { byte |= (bit as u8) << (7 - i); } payload.push(byte); } } Ok(payload) } fn binarize_otsu(img: &GrayImage) -> Vec<u8> { let mut histogram = [0u32; 256]; for p in img.pixels() { histogram[p.0[0] as usize] += 1; } let total = img.pixels().len() as u32; let mut sum = 0u64; for (i, &val) in histogram.iter().enumerate() { sum += (i as u64) * (val as u64); } let mut sum_b = 0u64; let mut w_b = 0u32; let mut max_var = 0.0f64; let mut threshold = 128u8; for (i, &val) in histogram.iter().enumerate() { w_b += val; if w_b == 0 { continue; } let w_f = total - w_b; if w_f == 0 { break; } sum_b += (i as u64) * (val as u64); let m_b = (sum_b as f64) / (w_b as f64); let m_f = ((sum - sum_b) as f64) / (w_f as f64); let var = (w_b as f64) * (w_f as f64) * (m_b - m_f).powi(2); if var > max_var { max_var = var; threshold = i as u8; } } img.pixels().map(|p| if p.0[0] < threshold { 0 } else { 255 }).collect() } fn find_markers(binary: &[u8], w: u32, h: u32) -> Result<((u32,u32), (u32,u32), (u32,u32), (u32,u32))> { let mut min_x = w; let mut max_x = 0; let mut min_y = h; let mut max_y = 0; for y in 0..h { for x in 0..w { if binary[(y * w + x) as usize] == 0 { if x < min_x { min_x = x; } if x > max_x { max_x = x; } if y < min_y { min_y = y; } if y > max_y { max_y = y; } } } } if min_x >= w || max_x == 0 { bail!("No markers found in image"); } Ok(((min_x, min_y), (max_x, min_y), (min_x, max_y), (max_x, max_y))) }